public class MainActivity extends Activity {
    static final int BG=0xFFF6F7FB,WHITE=0xFFFFFFFF,INK=0xFF202944,MUTED=0xFF69728A,BLUE=0xFF3446C8,LIGHT=0xFFE9ECFF,MINT=0xFFE1F4E9;
    LinearLayout root,body; long current=-1; Bitmap cropBitmap; CropView cropView; TextView cropLabel,runtimeLabel;
    EditText repeats,interval,timeout,threshold;
    boolean saving=false;
    final Handler handler=new Handler(Looper.getMainLooper());
    final Runnable refresh=new Runnable(){public void run(){if(runtimeLabel!=null)runtimeLabel.setText(AutoService.running?AutoService.status:(AutoService.instance!=null?AutoService.status:"Chưa bật Trợ năng"));handler.postDelayed(this,500);}};
    @Override public void onCreate(Bundle state){super.onCreate(state);current=MacroStore.prefs(this).getLong("selected",-1);if(state!=null){current=state.getLong("current",current);if(state.getBoolean("crop",false))loadCrop(new File(getCacheDir(),"crop-source.png"));}getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(0,()->onBackPressed());handler.post(refresh);}
    @Override public void onResume(){super.onResume();handleCapture();if(cropBitmap!=null)renderCrop();else render();}
    @Override public void onPause(){saveConfig(false);super.onPause();}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handleCapture();if(cropBitmap!=null)renderCrop();}
    @Override public void onSaveInstanceState(Bundle out){saveConfig(false);out.putLong("current",current);out.putBoolean("crop",cropBitmap!=null);super.onSaveInstanceState(out);}
    @Override public void onDestroy(){handler.removeCallbacksAndMessages(null);if(cropBitmap!=null&&!cropBitmap.isRecycled())cropBitmap.recycle();super.onDestroy();}
    void handleCapture(){if(getIntent().getBooleanExtra("capture",false)||MacroStore.prefs(this).getBoolean("captureReady",false)){getIntent().removeExtra("capture");MacroStore.prefs(this).edit().putBoolean("captureReady",false).apply();current=MacroStore.prefs(this).getLong("selected",current);File captured=new File(getFilesDir(),"capture.png");if(loadCrop(captured)){saveCropCache();captured.delete();}else toast("Không đọc được ảnh chụp. Hãy thử chụp lại.");}}
    int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
    LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h));}
    TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setTypeface(Typeface.create(bold?"sans-serif-medium":"sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));t.setIncludeFontPadding(false);t.setLineSpacing(dp(2),1);return t;}
    GradientDrawable bg(int color,int radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));return g;}
    void click(View v,int color,int radius,Runnable run){v.setBackground(new RippleDrawable(ColorStateList.valueOf(0x203446C8),bg(color,radius),bg(WHITE,radius)));v.setClickable(true);v.setFocusable(true);v.setOnClickListener(w->run.run());}
    void gap(LinearLayout l,int h){l.addView(new View(this),lp(1,h));}
    void space(LinearLayout l,int w){l.addView(new View(this),lp(w,1));}
    void flex(LinearLayout l,View v){l.addView(v,new LinearLayout.LayoutParams(0,-2,1));}
    TextView button(String title,boolean primary,Runnable r){TextView t=text(title,14,primary?WHITE:BLUE,true);t.setGravity(Gravity.CENTER);t.setPadding(dp(16),dp(14),dp(16),dp(14));t.setMinHeight(dp(50));click(t,primary?BLUE:LIGHT,16,r);return t;}
    LinearLayout card(int color){LinearLayout c=col();c.setPadding(dp(18),dp(18),dp(18),dp(18));c.setBackground(bg(color,22));LinearLayout.LayoutParams p=lp(-1,-2);p.bottomMargin=dp(12);body.addView(c,p);return c;}
    void section(String title,String count){LinearLayout r=row();flex(r,text(title,18,INK,true));if(count!=null)r.addView(text(count,11,MUTED,false));LinearLayout.LayoutParams p=lp(-1,-2);p.topMargin=dp(18);p.bottomMargin=dp(14);body.addView(r,p);}
    void scaffold(String title){
        repeats=interval=timeout=threshold=null;runtimeLabel=null;root=col();root.setBackgroundColor(BG);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();
        LinearLayout header=row();header.setPadding(dp(20),dp(16),dp(20),dp(12));
        if(current>=0){TextView back=text("‹",32,BLUE,true);back.setGravity(Gravity.CENTER);back.setContentDescription("Về danh sách kịch bản");click(back,LIGHT,16,()->{if(!saveConfig(true))return;current=-1;MacroStore.prefs(this).edit().putLong("selected",current).apply();render();});header.addView(back,lp(46,46));}else{ImageView icon=new ImageView(this);icon.setImageResource(R.drawable.ic_brand);icon.setContentDescription("Chạm Ảnh");header.addView(icon,lp(46,46));}
        space(header,12);LinearLayout copy=col();copy.addView(text(title,22,INK,true));gap(copy,4);copy.addView(text("Thấy hình. Chạm đúng.",11,MUTED,false));flex(header,copy);TextView help=text("?",18,BLUE,true);help.setGravity(Gravity.CENTER);help.setContentDescription("Hướng dẫn sử dụng");click(help,LIGHT,24,()->help());header.addView(help,lp(48,48));root.addView(header);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setVerticalScrollBarEnabled(false);body=col();body.setPadding(dp(20),dp(12),dp(20),dp(24));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
    }
    void render(){
        if(cropBitmap!=null){renderCrop();return;}
        JSONObject macro=current>=0?MacroStore.find(this,current):null;if(current>=0&&macro==null)current=-1;
        scaffold(current<0?"Chạm Ảnh":"Kịch bản");statusCard();if(current<0)home();else detail(macro);
    }
    void statusCard(){LinearLayout c=card(INK);LinearLayout r=row();flex(r,text(AutoService.running?"ĐANG CHẠY":"ĐIỀU KHIỂN TỰ ĐỘNG",10,0xFFCBD4FF,true));TextView stop=text("Dừng",12,WHITE,true);stop.setGravity(Gravity.CENTER);click(stop,0xFF414D6C,12,()->{if(AutoService.instance!=null)AutoService.instance.stopMacro("Đã dừng theo yêu cầu");});r.addView(stop,lp(64,44));c.addView(r);gap(c,14);runtimeLabel=text(AutoService.instance==null?"Chưa bật Trợ năng":AutoService.status,21,WHITE,true);c.addView(runtimeLabel);gap(c,9);c.addView(text("Ảnh xử lý trên máy · Không cần root",11,0xFFBDC5DD,false));if(AutoService.instance==null){gap(c,16);c.addView(button("Bật quyền Trợ năng",true,()->enableService()),lp(-1,-2));}}
    void home(){
        section("Kịch bản của bạn",MacroStore.all(this).length()+" kịch bản");body.addView(button("＋  Tạo kịch bản mới",true,()->newMacro()),lp(-1,-2));gap(body,16);
        JSONArray a=MacroStore.all(this);if(a.length()==0){LinearLayout c=card(WHITE);gap(c,12);c.addView(text("Tự động từ một ảnh mẫu.",23,INK,true));gap(c,10);c.addView(text("Lưu ảnh nút cần chạm, sắp xếp thành các bước và để Chạm Ảnh tìm đúng vị trí trên màn hình.",14,MUTED,false));gap(c,12);}
        for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;LinearLayout c=card(WHITE);LinearLayout r=row();TextView mark=text("▣",24,BLUE,true);mark.setGravity(Gravity.CENTER);mark.setBackground(bg(LIGHT,14));r.addView(mark,lp(48,48));space(r,12);LinearLayout copy=col();copy.addView(text(o.optString("name"),17,INK,true));gap(copy,6);JSONArray steps=o.optJSONArray("steps");copy.addView(text((steps==null?0:steps.length())+" bước  ·  "+o.optInt("repeat",1)+" vòng lặp",12,MUTED,false));flex(r,copy);r.addView(text("›",26,MUTED,false));c.addView(r);click(c,WHITE,22,()->{current=o.optLong("id");MacroStore.prefs(this).edit().putLong("selected",current).apply();render();});}
        section("Bắt đầu thật đơn giản",null);instruction("01","Lấy ảnh mẫu","Chụp màn hình ứng dụng đích hoặc chọn ảnh có sẵn.");instruction("02","Cắt vùng cần tìm","Chọn riêng nút hoặc biểu tượng có chi tiết rõ.");instruction("03","Chạy và quan sát","Chạm Ảnh tìm mẫu, chạm tâm ảnh rồi chuyển bước.");
        gap(body,12);body.addView(text("Bản thử nghiệm độc lập, không thuộc Macrofy. Android 11 trở lên.",11,MUTED,false));
    }
    void instruction(String n,String title,String detail){LinearLayout c=card(WHITE);LinearLayout r=row();TextView num=text(n,16,BLUE,true);r.addView(num,lp(38,-2));LinearLayout copy=col();copy.addView(text(title,14,INK,true));gap(copy,5);copy.addView(text(detail,12,MUTED,false));flex(r,copy);c.addView(r);}
    void newMacro(){EditText name=input("Tên kịch bản","",false);LinearLayout b=dialogBox();b.addView(name,lp(-1,-2));AlertDialog d=new AlertDialog.Builder(this).setTitle("Kịch bản mới").setView(b).setPositiveButton("Tạo",null).setNegativeButton("Hủy",null).create();d.setOnShowListener(v->{style(d);d.getButton(-1).setOnClickListener(w->{String s=name.getText().toString().trim();if(s.isEmpty()){name.setError("Nhập tên kịch bản");return;}current=MacroStore.create(this,s).optLong("id");MacroStore.prefs(this).edit().putLong("selected",current).apply();d.dismiss();render();});});d.show();}
    void detail(JSONObject macro){
        if(macro==null)return;LinearLayout title=row();flex(title,text(macro.optString("name"),26,INK,true));TextView edit=text("Sửa",12,BLUE,true);edit.setGravity(Gravity.CENTER);click(edit,LIGHT,14,()->rename());title.addView(edit,lp(56,48));body.addView(title);gap(body,8);body.addView(text("Tìm ảnh → chạm hoặc chờ → bước tiếp theo",12,MUTED,false));
        JSONArray steps=macro.optJSONArray("steps");if(steps==null)steps=new JSONArray();section("Chuỗi thao tác",steps.length()+" / 20 bước");
        for(int i=0;i<steps.length();i++)stepCard(steps.optJSONObject(i),i,steps.length());
        if(steps.length()==0){LinearLayout empty=card(WHITE);empty.addView(text("Thêm ảnh mẫu đầu tiên",18,INK,true));gap(empty,8);empty.addView(text("Ảnh mẫu nên lấy từ đúng thiết bị và đúng kích thước hiển thị của ứng dụng đích.",13,MUTED,false));}
        LinearLayout add=row();add.addView(button("＋  Chọn ảnh",false,()->importImage()),new LinearLayout.LayoutParams(0,-2,1));space(add,10);add.addView(button("▣  Chụp mẫu",false,()->capture()),new LinearLayout.LayoutParams(0,-2,1));body.addView(add);
        section("Thiết lập nhận diện",null);LinearLayout settings=card(WHITE);LinearLayout first=row(),second=row();repeats=numberField(first,"Số vòng lặp",macro.optInt("repeat",1),"1–1000 vòng");space(first,14);threshold=numberField(first,"Độ khớp (%)",macro.optInt("threshold",92),"70–99%, nên ≥90");settings.addView(first);gap(settings,18);interval=numberField(second,"Quét mỗi (ms)",macro.optInt("interval",1500),"1000–60000 ms");space(second,14);timeout=numberField(second,"Chờ ảnh (giây)",macro.optInt("timeout",15),"1–120 giây / bước");settings.addView(second);gap(settings,18);settings.addView(text("Không thấy ảnh trong thời gian chờ: dừng kịch bản. Ảnh phải cùng tỷ lệ với màn hình, chưa hỗ trợ tự đổi kích thước. Tổng ảnh mẫu tối đa 4 megapixel.",12,MUTED,false));
        body.addView(button("Lưu thiết lập",false,()->{if(saveConfig(true))toast("Đã lưu thiết lập");}),lp(-1,-2));gap(body,10);body.addView(button("▶  Chạy sau 5 giây",true,()->runMacro()),lp(-1,-2));gap(body,16);body.addView(text("Sau khi bấm Chạy, chuyển sang ứng dụng đích. Dùng nút DỪNG nổi để kết thúc bất cứ lúc nào.",12,MUTED,false));gap(body,18);body.addView(button("Xóa kịch bản",false,()->confirm("Xóa kịch bản?","Các bước và ảnh mẫu của kịch bản này sẽ bị xóa.",()->{if(AutoService.running&&AutoService.activeMacroId==current&&AutoService.instance!=null)AutoService.instance.stopMacro("Kịch bản đã bị xóa");MacroStore.delete(this,current);current=-1;MacroStore.prefs(this).edit().putLong("selected",-1).apply();render();})),lp(-1,-2));
    }
    EditText numberField(LinearLayout parent,String label,int value,String hint){LinearLayout box=col();box.addView(text(label,12,MUTED,false));gap(box,8);EditText e=input("",String.valueOf(value),true);box.addView(e,lp(-1,-2));gap(box,6);box.addView(text(hint,10,MUTED,false));parent.addView(box,new LinearLayout.LayoutParams(0,-2,1));return e;}
    boolean saveConfig(boolean show){if(saving||current<0||repeats==null)return true;saving=true;try{JSONObject o=MacroStore.find(this,current);if(o==null)return false;int r=Integer.parseInt(repeats.getText().toString()),i=Integer.parseInt(interval.getText().toString()),t=Integer.parseInt(timeout.getText().toString()),p=Integer.parseInt(threshold.getText().toString());if(r<1||r>1000||i<1000||i>60000||t<1||t>120||p<70||p>99){if(show)toast("Kiểm tra giới hạn số dưới từng ô thiết lập");return false;}o.put("repeat",r).put("interval",i).put("timeout",t).put("threshold",p);MacroStore.put(this,o);return true;}catch(Exception e){if(show)toast("Nhập số nguyên hợp lệ trong các ô thiết lập");return false;}finally{saving=false;}}
    void stepCard(JSONObject step,int index,int count){if(step==null)return;LinearLayout c=card(WHITE);LinearLayout r=row();ImageView preview=new ImageView(this);preview.setScaleType(ImageView.ScaleType.CENTER_CROP);preview.setBackground(bg(BG,12));try{BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;File f=MacroStore.image(this,step.optString("image"));BitmapFactory.decodeFile(f.getPath(),opts);opts.inSampleSize=Math.max(1,Math.max(opts.outWidth,opts.outHeight)/150);opts.inJustDecodeBounds=false;preview.setImageBitmap(BitmapFactory.decodeFile(f.getPath(),opts));}catch(Exception e){}preview.setContentDescription("Ảnh mẫu bước "+(index+1));r.addView(preview,lp(64,64));space(r,14);LinearLayout copy=col();copy.addView(text((index+1)+". "+step.optString("label","Ảnh mẫu"),15,INK,true));gap(copy,7);copy.addView(text(("wait".equals(step.optString("action"))?"Chờ thấy ảnh":"Chạm vào tâm ảnh")+" · Nghỉ "+step.optInt("delay",500)+" ms",11,MUTED,false));flex(r,copy);c.addView(r);gap(c,14);LinearLayout actions=row();actions.addView(button("Sửa bước",false,()->editStep(index)),new LinearLayout.LayoutParams(0,-2,1));if(index>0){space(actions,8);actions.addView(button("↑",false,()->moveStep(index,-1)),lp(48,-2));}if(index<count-1){space(actions,8);actions.addView(button("↓",false,()->moveStep(index,1)),lp(48,-2));}c.addView(actions);}
    void moveStep(int idx,int delta){if(!saveConfig(true))return;try{JSONObject o=MacroStore.find(this,current);JSONArray a=o.getJSONArray("steps");JSONObject one=a.getJSONObject(idx),two=a.getJSONObject(idx+delta);a.put(idx,two);a.put(idx+delta,one);MacroStore.put(this,o);render();}catch(Exception e){toast("Không đổi được thứ tự");}}
    void rename(){if(!saveConfig(true))return;JSONObject o=MacroStore.find(this,current);EditText name=input("Tên kịch bản",o.optString("name"),false);LinearLayout b=dialogBox();b.addView(name,lp(-1,-2));AlertDialog d=new AlertDialog.Builder(this).setTitle("Đổi tên").setView(b).setPositiveButton("Lưu",null).setNegativeButton("Hủy",null).create();d.setOnShowListener(v->{style(d);d.getButton(-1).setOnClickListener(w->{if(name.getText().toString().trim().isEmpty()){name.setError("Nhập tên");return;}try{o.put("name",name.getText().toString().trim());MacroStore.put(this,o);d.dismiss();render();}catch(Exception e){toast("Không lưu được");}});});d.show();}
    void editStep(int idx){if(AutoService.running){toast("Dừng kịch bản trước khi sửa bước");return;}if(!saveConfig(true))return;JSONObject o=MacroStore.find(this,current);JSONObject step=o.optJSONArray("steps").optJSONObject(idx);LinearLayout b=dialogBox();EditText name=input("Tên bước",step.optString("label"),false);b.addView(name,lp(-1,-2));gap(b,12);b.addView(text("Nghỉ sau bước này (0–10000 ms)",12,MUTED,false));gap(b,8);EditText delay=input("",String.valueOf(step.optInt("delay",500)),true);b.addView(delay,lp(-1,-2));gap(b,12);Switch wait=new Switch(this);wait.setText("Chỉ chờ thấy ảnh, không chạm");wait.setTextSize(13);wait.setTextColor(INK);wait.setChecked("wait".equals(step.optString("action")));wait.setMinHeight(dp(48));b.addView(wait,lp(-1,-2));AlertDialog d=new AlertDialog.Builder(this).setTitle("Bước "+(idx+1)).setView(b).setPositiveButton("Lưu",null).setNegativeButton("Hủy",null).setNeutralButton("Xóa",null).create();d.setOnShowListener(v->{style(d);d.getButton(-1).setOnClickListener(w->{try{int ms=Integer.parseInt(delay.getText().toString());if(ms<0||ms>10000){delay.setError("Từ 0 đến 10000");return;}String s=name.getText().toString().trim();if(s.isEmpty()){name.setError("Nhập tên bước");return;}step.put("label",s).put("delay",ms).put("action",wait.isChecked()?"wait":"tap");MacroStore.put(this,o);d.dismiss();render();}catch(Exception e){toast("Kiểm tra số mili giây");}});d.getButton(-3).setOnClickListener(w->confirm("Xóa bước này?","Ảnh mẫu của bước này cũng sẽ bị xóa.",()->{try{MacroStore.image(this,step.optString("image")).delete();o.optJSONArray("steps").remove(idx);MacroStore.put(this,o);d.dismiss();render();}catch(Exception e){toast("Không xóa được bước");}}));});d.show();}
    boolean canAdd(){if(!saveConfig(true))return false;JSONObject o=MacroStore.find(this,current);if(o==null)return false;if(o.optJSONArray("steps").length()>=20){toast("Tối đa 20 bước trong một kịch bản");return false;}if(AutoService.running){toast("Hãy dừng kịch bản trước khi sửa ảnh mẫu");return false;}return true;}
    void importImage(){if(!canAdd())return;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,10);}catch(Exception e){toast("Không mở được trình chọn ảnh");}}
    void capture(){if(!canAdd())return;if(AutoService.instance==null){enableService();return;}MacroStore.prefs(this).edit().putLong("selected",current).apply();AutoService.instance.showCaptureTool();moveTaskToBack(true);}
    @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=10||result!=RESULT_OK||data==null||data.getData()==null)return;try{Uri uri=data.getData();BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,opt);}if(opt.outWidth<=0||opt.outHeight<=0||((long)opt.outWidth*opt.outHeight)>8000000){toast("Chọn ảnh chụp màn hình nhỏ hơn 8 megapixel");return;}opt.inJustDecodeBounds=false;opt.inPreferredConfig=Bitmap.Config.ARGB_8888;try(InputStream in=getContentResolver().openInputStream(uri)){cropBitmap=BitmapFactory.decodeStream(in,null,opt);}if(cropBitmap==null)throw new IOException();saveCropCache();renderCrop();}catch(OutOfMemoryError e){toast("Ảnh quá lớn cho bộ nhớ máy. Hãy chọn ảnh nhỏ hơn.");}catch(Exception e){toast("Không đọc được ảnh. Hãy chọn PNG hoặc JPG.");}}
    boolean loadCrop(File f){try{BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;BitmapFactory.decodeFile(f.getPath(),opts);if(opts.outWidth<=0||opts.outHeight<=0||(long)opts.outWidth*opts.outHeight>8000000)return false;opts.inJustDecodeBounds=false;opts.inPreferredConfig=Bitmap.Config.ARGB_8888;Bitmap b=BitmapFactory.decodeFile(f.getPath(),opts);if(b==null)return false;if(cropBitmap!=null)cropBitmap.recycle();cropBitmap=b;return true;}catch(OutOfMemoryError e){return false;}catch(Exception e){return false;}}
    void saveCropCache(){try(FileOutputStream out=new FileOutputStream(new File(getCacheDir(),"crop-source.png"))){cropBitmap.compress(Bitmap.CompressFormat.PNG,100,out);}catch(Exception e){}}
    void renderCrop(){
        if(cropBitmap==null)return;repeats=interval=timeout=threshold=null;runtimeLabel=null;root=col();root.setBackgroundColor(BG);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();
        LinearLayout top=col();top.setPadding(dp(20),dp(18),dp(20),dp(12));top.addView(text("Cắt ảnh mẫu",24,INK,true));gap(top,8);top.addView(text("Kéo một hình chữ nhật quanh nút cần tìm. Tránh chọn khoảng trống hoặc toàn màn hình.",13,MUTED,false));root.addView(top);
        cropView=new CropView();root.addView(cropView,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout bottom=col();bottom.setPadding(dp(20),dp(14),dp(20),dp(18));cropLabel=text("Chạm và kéo trên ảnh để chọn vùng",12,MUTED,false);bottom.addView(cropLabel);gap(bottom,12);LinearLayout controls=row();controls.addView(button("Hủy",false,()->cancelCrop()),new LinearLayout.LayoutParams(0,-2,1));space(controls,12);controls.addView(button("Lưu ảnh mẫu",true,()->saveTemplate()),new LinearLayout.LayoutParams(0,-2,1));bottom.addView(controls);root.addView(bottom);
    }
    void cancelCrop(){if(cropBitmap!=null){cropBitmap.recycle();cropBitmap=null;}new File(getCacheDir(),"crop-source.png").delete();render();}
    void saveTemplate(){try{saveTemplateNow();}catch(OutOfMemoryError e){toast("Không đủ bộ nhớ. Hãy chọn vùng ảnh nhỏ hơn.");}}
    void saveTemplateNow(){
        Rect r=cropView.selection();if(r==null||r.width()<12||r.height()<12){toast("Chọn vùng ít nhất 12 × 12 pixel");return;}if(r.width()>1024||r.height()>1024){toast("Chọn vùng nhỏ hơn, tối đa 1024 × 1024 pixel");return;}
        Bitmap b=Bitmap.createBitmap(cropBitmap,r.left,r.top,r.width(),r.height());if(b==cropBitmap)b=b.copy(Bitmap.Config.ARGB_8888,false);int[] pixels=new int[b.getWidth()*b.getHeight()];b.getPixels(pixels,0,b.getWidth(),0,0,b.getWidth(),b.getHeight());if(!ImageMatcher.hasUsableDetail(pixels,b.getWidth(),b.getHeight())){b.recycle();toast("Vùng này ít chi tiết. Hãy chọn nút có chữ hoặc biểu tượng rõ.");return;}
        String file="sample_"+System.currentTimeMillis()+".png";try{JSONObject o=MacroStore.find(this,current);if(o==null)throw new IOException();JSONArray steps=o.getJSONArray("steps");if(steps.length()>=20){toast("Đã đủ 20 bước");return;}long total=(long)b.getWidth()*b.getHeight();for(int k=0;k<steps.length();k++){BitmapFactory.Options bound=new BitmapFactory.Options();bound.inJustDecodeBounds=true;BitmapFactory.decodeFile(MacroStore.image(this,steps.optJSONObject(k).optString("image")).getPath(),bound);total+=(long)Math.max(0,bound.outWidth)*Math.max(0,bound.outHeight);}if(total>4000000){toast("Tổng ảnh mẫu vượt 4 megapixel. Hãy cắt vùng nhỏ hơn.");return;}try(FileOutputStream out=new FileOutputStream(MacroStore.image(this,file))){if(!b.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException();}steps.put(new JSONObject().put("image",file).put("label","Ảnh mẫu "+(steps.length()+1)).put("action","tap").put("delay",500));MacroStore.put(this,o);toast("Đã thêm ảnh mẫu");cancelCrop();}catch(Exception e){try{MacroStore.image(this,file).delete();}catch(Exception ignored){}toast("Không lưu được ảnh mẫu");}finally{b.recycle();}
    }
    void runMacro(){if(!saveConfig(true))return;if(AutoService.running){toast("Hãy dừng phiên đang chạy trước");return;}if(AutoService.instance==null){enableService();return;}JSONObject o=MacroStore.find(this,current);if(o==null||o.optJSONArray("steps").length()==0){toast("Hãy thêm ít nhất một ảnh mẫu");return;}AutoService.instance.startMacro(o);toast("Chuyển sang ứng dụng đích trong 5 giây");}
    void enableService(){AlertDialog d=new AlertDialog.Builder(this).setTitle("Cho phép điều khiển qua Trợ năng").setMessage("Chạm Ảnh dùng quyền Trợ năng để chụp màn hình và gửi thao tác chạm theo kịch bản bạn tạo. Chỉ chạy sau khi bạn bấm Chạy.\n\nẢnh xử lý trên điện thoại, không gửi lên mạng. Có nút DỪNG nổi khi chạy; bạn có thể tắt dịch vụ trong Cài đặt.\n\nMở Cài đặt → tìm Chạm Ảnh → bật dịch vụ. Việc bật quyền không tự khởi chạy kịch bản.").setPositiveButton("Mở cài đặt",(v,w)->{try{startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));}catch(Exception e){toast("Hãy mở mục Trợ năng trong Cài đặt Android");}}).setNegativeButton("Để sau",null).create();d.setOnShowListener(v->style(d));d.show();}
    void help(){AlertDialog d=new AlertDialog.Builder(this).setTitle("Chạm Ảnh · 0.1.0").setMessage("1. Tạo kịch bản, bật dịch vụ Chạm Ảnh trong Trợ năng.\n2. Chọn ảnh chụp màn hình có sẵn, hoặc Chụp mẫu → chuyển đến ứng dụng đích → nhấn Chụp trên thanh nổi.\n3. Cắt riêng nút có chữ/biểu tượng. Mỗi mẫu tạo một bước; sửa bước để chọn chạm hoặc chỉ chờ.\n4. Chạy, chuyển ứng dụng trong 5 giây. Kéo thanh nổi để di chuyển, bấm DỪNG để kết thúc.\n\nGiữ nguyên hướng màn hình và tỷ lệ ảnh. Ứng dụng bảo vệ ảnh chụp hoặc màn hình khóa không được hỗ trợ. Độ khớp là điểm tương đồng ảnh, không bảo đảm chạm đúng 100%.\n\nẢnh và kịch bản lưu trên máy; không có quyền Internet. Gỡ ứng dụng sẽ xóa dữ liệu.\n\nBản thử nghiệm độc lập, không thuộc Macrofy.").setPositiveButton("Đã hiểu",null).create();d.setOnShowListener(v->style(d));d.show();}
    void confirm(String title,String message,Runnable run){AlertDialog d=new AlertDialog.Builder(this).setTitle(title).setMessage(message).setPositiveButton("Xóa",(v,w)->run.run()).setNegativeButton("Giữ lại",null).create();d.setOnShowListener(v->style(d));d.show();}
    LinearLayout dialogBox(){LinearLayout b=col();b.setPadding(dp(22),dp(10),dp(22),dp(10));return b;}
    EditText input(String hint,String value,boolean number){EditText e=new EditText(this);e.setHint(hint);e.setText(value);e.setTextColor(INK);e.setHintTextColor(MUTED);e.setTextSize(number?21:15);e.setPadding(dp(14),dp(13),dp(14),dp(13));e.setBackground(bg(BG,14));e.setSingleLine(true);e.setInputType(number?android.text.InputType.TYPE_CLASS_NUMBER:android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);e.setMinHeight(dp(52));return e;}
    void style(AlertDialog d){if(d.getWindow()!=null)d.getWindow().setBackgroundDrawable(bg(WHITE,24));d.getButton(-1).setTextColor(BLUE);d.getButton(-2).setTextColor(MUTED);d.getButton(-3).setTextColor(0xFFAD4D58);}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    @Override public void onBackPressed(){if(cropBitmap!=null){cancelCrop();return;}if(current>=0){if(!saveConfig(true))return;current=-1;MacroStore.prefs(this).edit().putLong("selected",-1).apply();render();return;}super.onBackPressed();}

    final class CropView extends View {
        final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG); final RectF image=new RectF();float startX,startY,endX,endY;boolean selected=false;
        CropView(){super(MainActivity.this);setBackgroundColor(0xFF12182C);setContentDescription("Kéo trên ảnh để chọn vùng nhận diện");}
        void fit(){if(cropBitmap==null)return;float scale=Math.min(getWidth()/(float)cropBitmap.getWidth(),getHeight()/(float)cropBitmap.getHeight());float w=cropBitmap.getWidth()*scale,h=cropBitmap.getHeight()*scale;image.set((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2);}
        @Override protected void onDraw(Canvas c){super.onDraw(c);if(cropBitmap==null)return;fit();paint.setStyle(Paint.Style.FILL);paint.setColor(WHITE);c.drawBitmap(cropBitmap,null,image,paint);if(!selected)return;RectF r=new RectF(Math.min(startX,endX),Math.min(startY,endY),Math.max(startX,endX),Math.max(startY,endY));paint.setColor(0x99000000);c.drawRect(image.left,image.top,image.right,r.top,paint);c.drawRect(image.left,r.bottom,image.right,image.bottom,paint);c.drawRect(image.left,r.top,r.left,r.bottom,paint);c.drawRect(r.right,r.top,image.right,r.bottom,paint);paint.setColor(0xFF84E8BC);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(2));c.drawRect(r,paint);paint.setStyle(Paint.Style.FILL);}
        @Override public boolean onTouchEvent(android.view.MotionEvent e){fit();float x=Math.max(image.left,Math.min(image.right,e.getX())),y=Math.max(image.top,Math.min(image.bottom,e.getY()));if(e.getAction()==MotionEvent.ACTION_DOWN){if(!image.contains(e.getX(),e.getY()))return false;selected=true;startX=endX=x;startY=endY=y;getParent().requestDisallowInterceptTouchEvent(true);}else if(e.getAction()==MotionEvent.ACTION_MOVE||e.getAction()==MotionEvent.ACTION_UP){endX=x;endY=y;if(e.getAction()==MotionEvent.ACTION_UP){getParent().requestDisallowInterceptTouchEvent(false);performClick();}}else return false;Rect r=selection();if(cropLabel!=null&&r!=null)cropLabel.setText("Vùng chọn: "+r.width()+" × "+r.height()+" pixel");invalidate();return true;}
        @Override public boolean performClick(){super.performClick();return true;}
        Rect selection(){if(!selected||image.width()<=0||cropBitmap==null)return null;int w=cropBitmap.getWidth(),h=cropBitmap.getHeight();return new Rect(Math.max(0,(int)((Math.min(startX,endX)-image.left)/image.width()*w)),Math.max(0,(int)((Math.min(startY,endY)-image.top)/image.height()*h)),Math.min(w,(int)Math.ceil((Math.max(startX,endX)-image.left)/image.width()*w)),Math.min(h,(int)Math.ceil((Math.max(startY,endY)-image.top)/image.height()*h)));}
    }
}
